static String json(Object value) {
    if (value == null) return "null";
    if (value instanceof Number || value instanceof Boolean) return value.toString();
    if (value instanceof Map<?, ?> map) return "{" + String.join(",", map.entrySet().stream().sorted(Comparator.comparing((entry)->String.valueOf(entry.getKey()))).map((entry)->json(String.valueOf(entry.getKey())) + ":" + json(entry.getValue())).toList()) + "}";
    if (value instanceof List<?> list) return "[" + String.join(",", list.stream().map(StudyAssistance::json).toList()) + "]";
    StringBuilder escaped = new StringBuilder("\"");
    for (char character : value.toString().toCharArray()) {
        if (character == '\\' || character == '\"') escaped.append('\\').append(character); else if (character < 32) escaped.append(String.format("\\u%04x", (int)character)); else escaped.append(character);
    }
    return escaped.append('\"').toString();
}

